"use strict";(self.webpackChunk_ai_autistic_intelligence_docusaurus_theme=self.webpackChunk_ai_autistic_intelligence_docusaurus_theme||[]).push([["7031"],{2777(e){e.exports=JSON.parse('{"version":{"pluginId":"nestjs-yalc","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/nestjs-yalc/overview","label":"Overview","docId":"overview","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/architecture","label":"Architecture","docId":"architecture","unlisted":false},{"type":"category","label":"docs","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/nestjs-yalc/docs/intro","label":"Introduction & Ecosystem Architecture","docId":"docs/intro","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/quickstart","label":"Quickstart & First Application Setup","docId":"docs/quickstart","unlisted":false},{"type":"category","label":"modules","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/nestjs-yalc/docs/modules/ag-grid","label":"AG-Grid Server-Side Integration & Query Transformers","docId":"docs/modules/ag-grid","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/crud-gen","label":"@nest-yalc-2/crud-gen","docId":"docs/modules/crud-gen","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/data-loader","label":"@nest-yalc-2/data-loader","docId":"docs/modules/data-loader","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/database","label":"@nest-yalc-2/database","docId":"docs/modules/database","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/logger","label":"@nest-yalc-2/logger","docId":"docs/modules/logger","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/observability","label":"@nest-yalc-2/observability","docId":"docs/modules/observability","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/sentinel","label":"@nest-yalc-2/sentinel","docId":"docs/modules/sentinel","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/kafka","label":"@nest-yalc-2/kafka","docId":"docs/modules/kafka","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/audit","label":"@nest-yalc-2/audit","docId":"docs/modules/audit","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/api-strategy","label":"API Strategy, Multi-Protocol Adapters & Contract Versioning","docId":"docs/modules/api-strategy","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/errors","label":"@nest-yalc-2/errors","docId":"docs/modules/errors","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/event-manager","label":"In-Memory & Distributed Event Manager","docId":"docs/modules/event-manager","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/field-middleware","label":"GraphQL Field Middleware & Dynamic Property Transformers","docId":"docs/modules/field-middleware","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/graphql","label":"@nest-yalc-2/graphql","docId":"docs/modules/graphql","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/jest","label":"@nest-yalc-2/jest","docId":"docs/modules/jest","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/app","label":"Application Lifecycle, Bootstrap & Module Composition","docId":"docs/modules/app","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/docs/modules/utils","label":"Core Utilities, Helpers & Object Manipulation","docId":"docs/modules/utils","unlisted":false}]}]},{"type":"category","label":"modules","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/nestjs-yalc/modules/logger","label":"Logger","docId":"modules/logger","unlisted":false},{"type":"link","href":"/docs/nestjs-yalc/modules/crud-gen","label":"CRUD Generator","docId":"modules/crud-gen","unlisted":false}]}]},"docs":{"architecture":{"id":"architecture","title":"Architecture","description":"NestJS-YALC is structured as a modular monorepo, providing a bridge between raw Node.js utilities and the NestJS dependency injection system.","sidebar":"tutorialSidebar"},"docs/intro":{"id":"docs/intro","title":"Introduction & Ecosystem Architecture","description":"Welcome to NestJS-YALC (Yet Another Layer of Convenience for NestJS), the enterprise-grade foundation framework for building scalable, high-performance microservices and monorepo applications in TypeScript and Node.js.","sidebar":"tutorialSidebar"},"docs/modules/ag-grid":{"id":"docs/modules/ag-grid","title":"AG-Grid Server-Side Integration & Query Transformers","description":"The @nestjs-yalc/ag-grid package provides enterprise-grade, server-side data grid processing for NestJS applications. It automatically translates frontend AG-Grid request payloads (containing complex filtering rules, multi-column sorting, pagination limits, and grouping expressions) into optimized TypeORM SelectQueryBuilder execution plans with parameterized SQL generation.","sidebar":"tutorialSidebar"},"docs/modules/api-strategy":{"id":"docs/modules/api-strategy","title":"API Strategy, Multi-Protocol Adapters & Contract Versioning","description":"The @nestjs-yalc/api-strategy package enforces standardized API design paradigms across REST, GraphQL, and Messaging protocols. It provides multi-protocol controller abstractions, automated URI versioning strategies, uniform response payload wrapping, and content-negotiation adapters.","sidebar":"tutorialSidebar"},"docs/modules/app":{"id":"docs/modules/app","title":"Application Lifecycle, Bootstrap & Module Composition","description":"The @nestjs-yalc/app module provides a standardized, enterprise-ready application bootstrapping kernel for NestJS microservices and monolithic servers. It abstracts boilerplate startup routines\u2014such as graceful shutdown signal handlers, unified configuration loading, global interceptors/filters registration, health-check lifecycle hooks, and multi-tenant context injection.","sidebar":"tutorialSidebar"},"docs/modules/audit":{"id":"docs/modules/audit","title":"@nest-yalc-2/audit","description":"@nest-yalc-2/audit provides enterprise compliance entity auditing and revision tracking for NestJS 11+. It automatically intercepts TypeORM entity mutation operations (INSERT, UPDATE, DELETE), capturing before/after field diffs and correlating mutations with the active authenticated user ID.","sidebar":"tutorialSidebar"},"docs/modules/crud-gen":{"id":"docs/modules/crud-gen","title":"@nest-yalc-2/crud-gen","description":"\u{1F4A1} 1. What It Is & Architectural Purpose","sidebar":"tutorialSidebar"},"docs/modules/data-loader":{"id":"docs/modules/data-loader","title":"@nest-yalc-2/data-loader","description":"\u{1F4A1} 1. What It Is & Architectural Purpose","sidebar":"tutorialSidebar"},"docs/modules/database":{"id":"docs/modules/database","title":"@nest-yalc-2/database","description":"@nest-yalc-2/database is the enterprise persistence infrastructure module for NestJS 11+. It provides dynamic multi-database connection management, transactional repository runners, automated database migrations, and entity seeding helpers powered by TypeORM and @node-yalc.","sidebar":"tutorialSidebar"},"docs/modules/errors":{"id":"docs/modules/errors","title":"@nest-yalc-2/errors","description":"@nest-yalc-2/errors provides standardized NestJS 11+ Exception Filters mapping @node-yalc/errors to RFC 7807 Problem Details HTTP and GraphQL error responses.","sidebar":"tutorialSidebar"},"docs/modules/event-manager":{"id":"docs/modules/event-manager","title":"In-Memory & Distributed Event Manager","description":"The @nestjs-yalc/event-manager package provides a unified event bus for NestJS microservices. It bridges local, process-level event emitters (built on Node.js EventEmitter2) with external distributed messaging brokers (such as Apache Kafka and RabbitMQ), providing transactional event delivery, wildcard topic subscriptions, and type-safe payload dispatches.","sidebar":"tutorialSidebar"},"docs/modules/field-middleware":{"id":"docs/modules/field-middleware","title":"GraphQL Field Middleware & Dynamic Property Transformers","description":"The @nestjs-yalc/field-middleware package provides fine-grained property-level access control, dynamic field encryption, value maskers, and runtime formatting transformers for GraphQL schemas and REST DTO entities.","sidebar":"tutorialSidebar"},"docs/modules/graphql":{"id":"docs/modules/graphql","title":"@nest-yalc-2/graphql","description":"@nest-yalc-2/graphql provides dynamic GraphQL server configuration for NestJS 11+, supporting both Apollo Server and Fastify Mercurius, Apollo Federation v2 schema stitching, custom scalar registration, and field-level execution guardrails.","sidebar":"tutorialSidebar"},"docs/modules/jest":{"id":"docs/modules/jest","title":"@nest-yalc-2/jest","description":"@nest-yalc-2/jest provides a multi-project test runner, custom matchers, SWC compiler integration, and HTML coverage report servers for NestJS monorepos.","sidebar":"tutorialSidebar"},"docs/modules/kafka":{"id":"docs/modules/kafka","title":"@nest-yalc-2/kafka","description":"@nest-yalc-2/kafka provides production-grade event streaming for NestJS 11+. It wraps KafkaJS and @kafkajs/confluent-schema-registry, enabling strongly-typed, schema-validated message producing and consuming across distributed microservices.","sidebar":"tutorialSidebar"},"docs/modules/logger":{"id":"docs/modules/logger","title":"@nest-yalc-2/logger","description":"@nest-yalc-2/logger provides a high-performance, structured Pino logging integration for NestJS 11+. It automatically correlates HTTP request IDs (X-Request-Id) across asynchronous execution contexts using Node.js AsyncLocalStorage, redacting sensitive payload data for GDPR and PCI-DSS compliance.","sidebar":"tutorialSidebar"},"docs/modules/observability":{"id":"docs/modules/observability","title":"@nest-yalc-2/observability","description":"@nest-yalc-2/observability provides enterprise distributed tracing, metrics collection, and exception tracking for NestJS 11+. It integrates OpenTelemetry OTLP exporters, Prometheus metric collectors, and Sentry error reporting into a unified NestJS module.","sidebar":"tutorialSidebar"},"docs/modules/sentinel":{"id":"docs/modules/sentinel","title":"@nest-yalc-2/sentinel","description":"@nest-yalc-2/sentinel is the security middleware and policy enforcement module for NestJS 11+. It enforces OWASP recommended HTTP security headers, CORS origin policies, request payload size bounds, and input sanitization across all REST and GraphQL endpoints.","sidebar":"tutorialSidebar"},"docs/modules/utils":{"id":"docs/modules/utils","title":"Core Utilities, Helpers & Object Manipulation","description":"The @nestjs-yalc/utils package is the core utility toolkit for the NestJS-Yalc ecosystem. It provides high-performance, type-safe utility functions for object manipulation, array operations, concurrent async processing, string transformations, class reflection helpers, and cryptographic hashing.","sidebar":"tutorialSidebar"},"docs/quickstart":{"id":"docs/quickstart","title":"Quickstart & First Application Setup","description":"This step-by-step guide walks you through setting up a complete enterprise NestJS microservice from scratch using the NestJS-YALC monorepo toolkit.","sidebar":"tutorialSidebar"},"modules/crud-gen":{"id":"modules/crud-gen","title":"CRUD Generator","description":"The @nest-yalc-2/crud-gen module is a powerful code generator that automates the creation of REST controllers and GraphQL resolvers based directly on your TypeORM entities.","sidebar":"tutorialSidebar"},"modules/logger":{"id":"modules/logger","title":"Logger","description":"The @nest-yalc-2/logger module provides a high-performance, Pino-based logging infrastructure for NestJS applications. It automatically correlates HTTP requests, Redacts sensitive information, and integrates seamlessly with OpenTelemetry for distributed tracing.","sidebar":"tutorialSidebar"},"overview":{"id":"overview","title":"Overview","description":"NestJS-YALC (Yet Another Library Collection) is an enterprise-grade library suite designed specifically for NestJS 11+ and TypeScript 6+. It extends the core NestJS framework with a collection of pre-built, production-ready modules that address the most common and complex challenges in enterprise backend development.","sidebar":"tutorialSidebar"}}}}')}}]);